import { useContext } from "react";
import Switch from "react-switch";
import { useTranslation } from "react-i18next";
import { Icon } from "@iconify/react";
import { TypeAnimation } from "react-type-animation";
import { ThemeContext, ThemeContextInterface } from "../providers";

const Header = () => {
  const { darkTheme, toggleTheme } = useContext(
    ThemeContext
  ) as ThemeContextInterface;

  const { t, i18n } = useTranslation();
  const titles = t("basic_info.titles", { returnObjects: true }) as string[];

  const handleLanguageChange = (
    event: React.ChangeEvent<HTMLSelectElement>
  ) => {
    i18n.changeLanguage(event.target.value);
  };

  return (
    <>
      <header className="h-[650px] w-[100%] bg-[#e0edf3] dark:bg-[#494949]">
        <div className="flex h-full flex-col items-center justify-center gap-5">
          <div>
            <Icon
              className="text-gray-dark"
              icon="la:laptop-code"
              style={{
                height: "100%",
                fontSize: 150,
              }}
            />
          </div>

          <h1 className="text-4xl font-bold text-gray-dark dark:text-white">
            {t("basic_info.name")}
          </h1>
          {titles.length > 1 ? (
            <TypeAnimation
              sequence={titles.flatMap((title) => [title, 1000])}
              wrapper="span"
              speed={50}
              className="text-regular text-2xl text-gray-dark dark:text-white"
              repeat={Infinity}
            />
          ) : (
            <span className="text-regular text-2xl text-gray-dark dark:text-white">
              {titles[0]}
            </span>
          )}
        </div>
        <div className="absolute top-4 right-4 flex items-center gap-4">
          <select
            value={i18n.language}
            onChange={handleLanguageChange}
            className="p-2 bg-white dark:bg-gray-800 text-black dark:text-white rounded-lg border border-gray-300 dark:border-gray-700 focus:outline-none focus:ring-2 focus:ring-blue-500 dark:focus:ring-blue-300"
          >
            <option value="en">English</option>
            <option value="zh">中文</option>
          </select>
          <Switch
            checked={darkTheme}
            onChange={toggleTheme}
            offColor="#818181"
            onColor="#818181"
            className="react-switch"
            width={90}
            height={40}
            uncheckedIcon={
              <Icon
                className="ml-5 h-full text-end text-[25px] text-gray-dark"
                icon="ic:outline-dark-mode"
              />
            }
            checkedIcon={
              <Icon
                className="ml-5 h-full text-end text-[25px] text-gray-dark"
                icon="ic:outline-light-mode"
              />
            }
          />
        </div>
      </header>
    </>
  );
};

export default Header;
